    right_start = zero_cols[-1] + 1

    def region_color(row, start, end):
        vals = {row[c] for c in range(start, end) if row[c] != 0}
        if len(vals) == 1:
            return next(iter(vals))
        return None

    # Build mapping from the top section
    mapping = {}
    for r in range(sep_row):
        left_color = region_color(grid[r], 0, left_end)
        right_color = region_color(grid[r], right_start, w)
        if left_color is not None and right_color is not None:
            mapping[left_color] = right_color

    inverse_mapping = {v: k for k, v in mapping.items()}

    out = [row[:] for row in grid]

    # Fill the bottom section
    for r in range(sep_row + 1, h):
        left_color = region_color(out[r], 0, left_end)
